<script setup lang="ts">
import * as T from 'three'
import { OrbitControls } from 'three/addons/controls/OrbitControls.js'
import { RoomEnvironment } from 'three/addons/environments/RoomEnvironment.js'
import gsap from 'gsap'
import { ScrollTrigger } from 'gsap/ScrollTrigger'
import { createVehicle } from '~/three/vehicle'
import { loadVehicle } from '~/three/loadVehicle'
const props=defineProps<{drive?:boolean}>(),emit=defineEmits<{ready:[],progress:[number],speed:[number],error:[string]}>()
const el=ref<HTMLDivElement>(),state=useAtelier();let renderer:T.WebGLRenderer,scene:T.Scene,camera:T.PerspectiveCamera,controls:OrbitControls,car:ReturnType<typeof createVehicle>,frame=0,pmrem:T.PMREMGenerator,env:T.Texture,world:any,rigid:any,rapier:any
let stopped=false,angle=0,cam=0,paused=false;const keys=new Set<string>();const reduced=()=>!state.motion.value;let resize:ResizeObserver;let trigger:ScrollTrigger|undefined;let floor:T.Mesh,key:T.DirectionalLight,fill:T.PointLight
function reset(){rigid?.setTranslation({x:0,y:.58,z:0},true);rigid?.setLinvel({x:0,y:0,z:0},true);angle=0}
function keyboard(e:KeyboardEvent){if(['INPUT','SELECT','TEXTAREA'].includes((e.target as HTMLElement)?.tagName))return;if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' '].includes(e.key))e.preventDefault();keys.add(e.key.toLowerCase());if(e.key.toLowerCase()==='r')reset();if(e.key.toLowerCase()==='c')cam=(cam+1)%3;if(e.key==='Escape')paused=!paused}
function release(e:KeyboardEvent){keys.delete(e.key.toLowerCase())}
onMounted(async()=>{try{
 await nextTick();if(!el.value)throw new Error('Scene container is not mounted. Please retry.');
 emit('progress',10);scene=new T.Scene();scene.background=new T.Color('#101313');scene.fog=new T.Fog('#101313',18,65)
 renderer=new T.WebGLRenderer({antialias:true,alpha:false});renderer.setPixelRatio(Math.min(devicePixelRatio,1.8));renderer.shadowMap.enabled=true;renderer.shadowMap.type=T.PCFSoftShadowMap;renderer.toneMapping=T.ACESFilmicToneMapping;renderer.toneMappingExposure=.85;el.value!.appendChild(renderer.domElement)
 camera=new T.PerspectiveCamera(36,1,.05,160);camera.position.set(-5.7,2.35,6.3);controls=new OrbitControls(camera,renderer.domElement);controls.target.set(0,.65,0);controls.enableDamping=true;controls.minDistance=3;controls.maxDistance=13;controls.maxPolarAngle=Math.PI/2-.03;controls.minPolarAngle=.25;controls.enablePan=false;controls.enabled=!props.drive
 emit('progress',35);pmrem=new T.PMREMGenerator(renderer);const room=new RoomEnvironment();env=pmrem.fromScene(room,.04).texture;scene.environment=env;room.dispose()
 scene.add(new T.HemisphereLight('#dcdfd2','#121712',.7));key=new T.DirectionalLight('#f5ffe3',4);key.position.set(-3,7,4);key.castShadow=true;key.shadow.mapSize.set(2048,2048);key.shadow.camera.left=-7;key.shadow.camera.right=7;key.shadow.camera.top=7;key.shadow.camera.bottom=-7;key.shadow.bias=-.001;scene.add(key)
 fill=new T.PointLight('#c7f2f0',70,25);fill.position.set(5,3,-4);scene.add(fill)
 floor=new T.Mesh(new T.PlaneGeometry(250,250),new T.MeshStandardMaterial({color:'#060807',metalness:0,roughness:1,envMapIntensity:.01}));floor.rotation.x=-Math.PI/2;floor.receiveShadow=true;scene.add(floor)
 if(props.drive){const grid=new T.GridHelper(180,180,'#1b241c','#131b14');grid.position.y=.002;scene.add(grid)}else{for(const radius of [3.7,3.73,4.4]){const ring=new T.Mesh(new T.RingGeometry(radius,radius+.008,128),new T.MeshBasicMaterial({color:'#475143',transparent:true,opacity:.3,side:T.DoubleSide}));ring.rotation.x=-Math.PI/2;ring.position.y=.003;scene.add(ring)}}
 emit('progress',65);car=await loadVehicle(state.car.value.shape,n=>emit('progress',n));car.body.color.set(state.paint.value);scene.add(car.root)
 if(props.drive){rapier=(await import('@dimforge/rapier3d-compat')).default;await rapier.init();world=new rapier.World({x:0,y:-9.81,z:0});world.createCollider(rapier.ColliderDesc.cuboid(100,.1,100).setTranslation(0,-.1,0));rigid=world.createRigidBody(rapier.RigidBodyDesc.dynamic().setTranslation(0,.58,0).enabledRotations(false,true,false).setLinearDamping(.7));world.createCollider(rapier.ColliderDesc.cuboid(2.3,.45,.95).setMass(1500),rigid)
 for(const z of [-13,13])for(let x=-70;x<70;x+=4){const barrier=new T.Mesh(new T.BoxGeometry(3.9,.7,.5),new T.MeshStandardMaterial({color:Math.round(x/4)%2?'#a6b86b':'#353d37'}));barrier.position.set(x,.35,z);scene.add(barrier);world.createCollider(rapier.ColliderDesc.cuboid(1.95,.35,.25).setTranslation(x,.35,z))}
 for(let x=-65;x<65;x+=6){const line=new T.Mesh(new T.PlaneGeometry(2,.08),new T.MeshBasicMaterial({color:'#777e70'}));line.rotation.x=-Math.PI/2;line.position.set(x,.006,0);scene.add(line)}window.addEventListener('keydown',keyboard);window.addEventListener('keyup',release)
 }else{gsap.registerPlugin(ScrollTrigger);if(state.motion.value){const from={x:-3.4,y:1.3,z:4};camera.position.set(from.x,from.y,from.z);gsap.to(camera.position,{x:-5.7,y:2.35,z:6.3,duration:2.5,ease:'power2.inOut'})}trigger=ScrollTrigger.create({trigger:document.body,start:'top top',end:'bottom bottom',onUpdate:s=>{if(reduced()||state.interior.value)return;const a=s.progress*Math.PI*1.5+.72;camera.position.set(-Math.cos(a)*8,2.2+Math.sin(s.progress*Math.PI),Math.sin(a)*8);controls.target.set(0,.65,0)}})}
 resize=new ResizeObserver(()=>{const w=el.value!.clientWidth,h=el.value!.clientHeight;renderer.setSize(w,h);camera.aspect=w/h;camera.fov=state.interior.value?60:camera.aspect<.8?65:36;camera.updateProjectionMatrix()});resize.observe(el.value!)
 emit('progress',90);await renderer.compileAsync(scene,camera);emit('progress',100);emit('ready')
 let last=performance.now(),count=0,sum=0
 function tick(now:number){if(stopped)return;frame=requestAnimationFrame(tick);const dt=Math.min((now-last)/1000,.04);last=now
  if(props.drive&&world&&!paused){const velocity=rigid.linvel();const forward=new T.Vector3(-Math.cos(angle),0,Math.sin(angle));let speed=velocity.x*forward.x+velocity.z*forward.z;const throttle=keys.has('w')||keys.has('arrowup'),braking=keys.has('s')||keys.has('arrowdown');speed+=(throttle?10:braking?-14:-speed*.35)*dt;if(keys.has(' '))speed*=Math.pow(.05,dt);speed=T.MathUtils.clamp(speed,-8,70);const steering=(keys.has('a')||keys.has('arrowleft')?1:0)-(keys.has('d')||keys.has('arrowright')?1:0);angle+=steering*dt*Math.min(Math.abs(speed)*.09,1.25)*Math.sign(speed);rigid.setLinvel({x:forward.x*speed,y:velocity.y,z:forward.z*speed},true);rigid.setRotation({x:0,y:Math.sin(angle/2),z:0,w:Math.cos(angle/2)},true);world.timestep=dt;world.step();const p=rigid.translation();if(Math.abs(p.x)>85||Math.abs(p.z)>30)reset();car.root.position.set(p.x,p.y-.48,p.z);car.root.rotation.y=angle;car.wheels.forEach(w=>{if(state.car.value.shape===8)w.rotation.x+=speed*dt*2;else w.rotation.z+=speed*dt*2});emit('speed',Math.round(Math.abs(speed)*3.6));const offset=cam===0?new T.Vector3(7,3,4):cam===1?new T.Vector3(-1.6,1.05,0):new T.Vector3(0,9,10);offset.applyAxisAngle(new T.Vector3(0,1,0),angle);camera.position.lerp(car.root.position.clone().add(offset),.07);camera.lookAt(car.root.position.clone().add(new T.Vector3(cam===1?-6:0,.8,0)))}else if(!props.drive)controls.update()
  renderer.render(scene,camera);sum+=dt;count++;if(count===120){if(sum>4&&state.quality.value==='High'){renderer.setPixelRatio(1)}sum=0;count=0}
 }frame=requestAnimationFrame(tick)
 }catch(e){emit('error',e instanceof Error?e.message:'WebGL unavailable')}})
watch(()=>state.paint.value,v=>car?.body.color.set(v));watch(()=>state.brakes.value,v=>car?.brake.color.set(v));watch(()=>state.wheels.value,v=>{if(!car)return;car.rim.color.set(['#a8acad','#191c1e','#bdab79'][v]!);car.spokes.forEach(g=>g.children.forEach((s,i)=>s.visible=v!==1||i%2===0))})
watch(()=>state.doors.value,v=>{car?.doors.forEach((d,i)=>gsap.to(d.rotation,{y:state.car.value.shape===8&&v?(i===0?-1:1):0,z:state.car.value.shape!==8&&v?-1.05:0,x:state.car.value.shape!==8&&v?(i===0?-.15:.15):0,duration:reduced()?.01:1.2,ease:'power2.inOut'}))})
watch(()=>state.interior.value,v=>{if(!camera)return;controls.enabled=false;const target=v?new T.Vector3(-.65,.85,.35):new T.Vector3(0,.65,0);controls.target.copy(target);controls.minDistance=v?.15:3;controls.maxDistance=v?1.15:13;controls.minPolarAngle=v?.4:.25;controls.maxPolarAngle=v?2.3:Math.PI/2-.03;gsap.to(camera,{fov:v?60:36,duration:1,onUpdate(){camera.updateProjectionMatrix()}});gsap.to(camera.position,{x:v?.25:-5.7,y:v?1.08:2.35,z:v?.35:6.3,duration:reduced()?.01:2,ease:'power2.inOut',onUpdate(){camera.lookAt(target)},onComplete(){controls.enabled=!props.drive}});if(car)car.glass.visible=!v})
watch(()=>state.lighting.value,v=>{if(!scene)return;const c=v==='Sunset'?'#473d34':v==='Night'?'#060b13':v==='Dark Room'?'#030404':'#101313';scene.background=new T.Color(c);(scene.fog as T.Fog).color.set(c);key.intensity=v==='Dark Room'?.9:v==='Night'?1.4:4;fill.color.set(v==='Sunset'?'#ffb477':'#c7f2f0')})
watch(()=>state.quality.value,v=>{if(renderer){renderer.setPixelRatio(Math.min(devicePixelRatio,{Low:.75,Medium:1,High:1.8,Ultra:2}[v]||1));key.shadow.mapSize.set(v==='Low'?512:2048,v==='Low'?512:2048);key.shadow.map?.dispose();key.shadow.map=null}})
watch(()=>state.shadows.value,v=>{if(renderer)renderer.shadowMap.enabled=v})
watch(()=>state.car.value.id,()=>{if(!scene)return;const old=car;gsap.to(old.root.scale,{x:.01,y:.01,z:.01,duration:.3,async onComplete(){scene.remove(old.root);old.dispose();try{car=await loadVehicle(state.car.value.shape,n=>emit('progress',n));car.body.color.set(state.paint.value);scene.add(car.root);car.root.scale.setScalar(.01);gsap.to(car.root.scale,{x:1,y:1,z:1,duration:.7})}catch(e){emit('error','Vehicle could not load. Please retry.')}}})})
onBeforeUnmount(()=>{stopped=true;cancelAnimationFrame(frame);trigger?.kill();resize?.disconnect();window.removeEventListener('keydown',keyboard);window.removeEventListener('keyup',release);world?.free();controls?.dispose();gsap.killTweensOf(camera?.position);car?.dispose();scene?.traverse(o=>{if(o instanceof T.Mesh){o.geometry.dispose();(Array.isArray(o.material)?o.material:[o.material]).forEach(m=>m.dispose())}});env?.dispose();pmrem?.dispose();renderer?.dispose()})
defineExpose({reset,cycleCamera(){cam=(cam+1)%3},setKey(key:string,down:boolean){down?keys.add(key):keys.delete(key)}})
</script>
<template><div ref="el" class="vehicle-canvas" aria-label="Interactive three-dimensional vehicle. Drag to rotate, scroll to zoom." /></template>
